using System;
using System.Collections;
using System.Collections.Generic;
using System.Text;
using UnityEditor;
using UnityEngine;

public class HexaTexture : EditorWindow
{
    public Texture2D HexaHorizonalTexture;
    public Texture2D HexaVerticalTexture;

    [ContextMenu("Write")]
    public void Write()
    {
        System.IO.File.WriteAllText("D:/texture_hexa1.text", Convert.ToBase64String(HexaVerticalTexture.EncodeToPNG()));
        System.IO.File.WriteAllText("D:/texture_hexa2.text", Convert.ToBase64String(HexaHorizonalTexture.EncodeToPNG()));
    }

    #region define
    static string Vertical=
        "";
    static string Horizonal =
        "";
    #endregion

    private static Texture2D _horizonalTexture2D;

    public static Texture2D HorizonalTexture2D
    {
        get
        {
            if (_horizonalTexture2D == null)
            {
                _horizonalTexture2D = new Texture2D(1, 1);
                _horizonalTexture2D.LoadImage(Convert.FromBase64String(Horizonal));
                _horizonalTexture2D.Apply();
            }
            return _horizonalTexture2D;
        }
    }

    private static Texture2D _verticalTexture2D;
    public static Texture2D VerticalTexture2D
    {
        get
        {
            if (_verticalTexture2D == null)
            {
                _verticalTexture2D = new Texture2D(1, 1);
                _verticalTexture2D.LoadImage(Convert.FromBase64String(Vertical));
                _verticalTexture2D.Apply();
            }
            return _verticalTexture2D;
        }
    }

}
